// js
// 勞動基準法 §24(1): first two overtime hours at 1.34, each further hour at 1.67; §24(1)(3) emergency extension pays every hour at 2.0.
const terms = get(ctx.subject.employment, 'terms', {});
const basis = get(terms, 'rate.unit', 'MONTHLY');
const normal = get(terms, 'normal_hours_per_day', null);
const day_hours = normal != null ? Number(normal) : ctx.lookup.normal_hours_per_day;
const allowances = Object.values(get(terms, 'allowances', {})).reduce(
  (sum, a) => sum + Number(get(a, 'amount', 0)),
  0
);
const unit_wage =
  basis === 'PIECE' || basis === 'HOURLY' ? Number(get(terms, 'rate.amount', 0))
  : basis === 'DAILY' ? Number(get(terms, 'rate.amount', 0)) / day_hours
  : (Number(get(terms, 'rate.amount', 0)) + allowances) / (ctx.lookup.monthly_divisor * day_hours);
const day_wage = unit_wage * day_hours;
const total = Number(get(ctx.run, 'source_manifest.overtime.OVERTIME', 0));
const emergency = Math.min(total, Number(get(ctx.run, 'source_manifest.overtime.OVERTIME_EMERGENCY', 0)));
const ordinary = Math.max(0, total - emergency);
const first_hours = Math.min(ordinary, ctx.lookup.first_two_hours);
return unit_wage * (first_hours * ctx.lookup.first_two_multiplier + (ordinary - first_hours) * ctx.lookup.further_multiplier) + emergency * unit_wage * ctx.lookup.emergency_multiplier;

