const terms = get(ctx.subject.employment, 'terms', {});
const basis = get(terms, 'rate.unit', 'MONTHLY');
const normal = get(terms, 'normal_hours_per_day', null);
const day_hours = normal != null ? Number(normal) : ctx.lookup.normal_hours_per_day;
const allowances = Object.values(get(terms, 'allowances', {})).reduce(
  (sum, a) => sum + Number(get(a, 'amount', 0)),
  0
);
const unit_wage =
  basis === 'PIECE' || basis === 'HOURLY' ? Number(get(terms, 'rate.amount', 0))
  : basis === 'DAILY' ? Number(get(terms, 'rate.amount', 0)) / day_hours
  : (Number(get(terms, 'rate.amount', 0)) + allowances) / (ctx.lookup.monthly_divisor * day_hours);
const day_wage = unit_wage * day_hours;
const hours = Number(get(ctx.run, 'source_manifest.overtime.REST_DAY_WORK', 0));
if (hours <= 0) return 0;
const first_hours = Math.min(hours, ctx.lookup.first_two_hours);
const middle_hours = Math.min(Math.max(hours - first_hours, 0), ctx.lookup.after_eight_hours - ctx.lookup.first_two_hours);
const last_hours = Math.max(hours - ctx.lookup.after_eight_hours, 0);
return unit_wage * (first_hours * ctx.lookup.first_two_multiplier + middle_hours * ctx.lookup.after_two_multiplier + last_hours * ctx.lookup.after_eight_multiplier);

